import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc = new Scanner(System.in);
		int t = sc.nextInt();
		
		while(t-->0)
		{
		    int n = sc.nextInt();
		    int m = 3*n;
		    
		    int[] arr = new int[m];
		    
		    for(int i=0;i<m;i++)
		    {
		        arr[i]=sc.nextInt();
		    }
		    
		    Arrays.sort(arr);
		    
		    long[] parti = new long[m+1];
		    
		    for(int i=0;i<m;i++)
		    {
		        parti[i+1]=parti[i]+arr[m-1-i];
		    }
		    
		    long ans = 0;
		    
		    for(int A=0;A<=n;A++)
		    {
		        int l=0,r=n-A;
		        while(l<r)
		        {
		            int B = (l+r)/2;
		            int x=A+2*B;
		            int y = m-2*A-B-1;
		            
		            if((long)arr[m-1-x]+arr[m-1-(x+1)]>=3L*arr[m-1-y])
		            {
		                l=B+1;
		            }
		            else
		            {
		                r=B;
		            }
		            
		        }
		            for(int b = Math.max(0,l-1);b<=l;b++)
		            {
		                int x = A+2*b;
		                int y = m-2*A-b;
		                ans = Math.max(ans,2*parti[A]+parti[x]+3*parti[y]);
		            }
		        }
		    
		    System.out.println(ans);
		}

	}
}
